import puppeteer from 'puppeteer-core';

const FILE = 'file:///home/dp/MyProjects/disc/.tmpwork/disc-pi-ihrbgwqf/run/index.html';
const results = [];
const ok = (name, cond, extra = '') => { results.push([cond ? 'PASS' : 'FAIL', name, extra]); };

const browser = await puppeteer.launch({
  executablePath: '/usr/bin/google-chrome',
  headless: 'new',
  args: ['--no-sandbox', '--disable-dev-shm-usage'],
});
const page = await browser.newPage();
await page.setViewport({ width: 1280, height: 900 });

const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const external = [];
page.on('request', r => { if (!r.url().startsWith('file://')) external.push(r.url()); });

await page.goto(FILE, { waitUntil: 'load' });

// 1. structure
ok('24 lists rendered', await page.$$eval('.list', l => l.length) === 24);
ok('96 items rendered', await page.$$eval('.item', l => l.length) === 96);
ok('step 0 active', await page.$eval('.pane.is-active', p => p.dataset.stepPane) === '0');
ok('prev disabled on step0', await page.$eval('[data-disc-prev]', b => b.disabled));
ok('finish hidden on step0', await page.$eval('[data-disc-finish]', b => b.hidden));
ok('progress 12.5%', await page.$eval('#discProgress', b => b.style.width) === '12.5%');

// 2. drag & drop (pointer events) within one list
const rect = await page.$eval('#draggable-list1 .item', el => {
  const r = el.getBoundingClientRect();
  return { x: r.x + r.width / 2, y: r.y + r.height / 2, h: r.height };
});
const second = await page.$eval('#draggable-list1 .item:nth-child(2)', el => {
  const r = el.getBoundingClientRect();
  return { y: r.y + r.height / 2 };
});
await page.mouse.move(rect.x, rect.y);
await page.mouse.down();
await page.mouse.move(rect.x, rect.y + 10, { steps: 3 });
await page.mouse.move(rect.x, second.y + rect.h, { steps: 8 });
await page.mouse.up();
const order1 = await page.$eval('#draggable-list1', ul =>
  Array.from(ul.children).map(li => li.className + ':' + (li.querySelector('.item__text')?.textContent || 'PH')).join('|'));
ok('drag moved item below 2nd', /item:.*\|item:/.test(order1) && !order1.includes('PH'), order1);
const noPh = await page.$$eval('.item-placeholder', p => p.length);
ok('placeholder removed after drop', noPh === 0);
const renum = await page.$$eval('#draggable-list1 .item__num', n => n.map(x => x.textContent).join(','));
ok('renumber 1..4', renum === '1,2,3,4', renum);

// cross-list drag
const srcBox = await page.$eval('#draggable-list1 .item', el => { const r = el.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2 }; });
const dstBox = await page.$eval('#draggable-list2', el => { const r = el.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + 40 }; });
await page.mouse.move(srcBox.x, srcBox.y);
await page.mouse.down();
await page.mouse.move(srcBox.x + 5, srcBox.y + 5, { steps: 3 });
await page.mouse.move(dstBox.x, dstBox.y, { steps: 10 });
await page.mouse.up();
const crossOk = await page.$eval('#draggable-list2', ul => ul.children.length === 5 && !ul.querySelector('.item-placeholder'));
const srcOk = await page.$eval('#draggable-list1', ul => ul.children.length === 3);
ok('cross-list drag', crossOk && srcOk);
// move it back for determinism
await page.$eval('#draggable-list2 .item', el => el.focus());
const firstIn2 = await page.$eval('#draggable-list2 .item', el => { const r = el.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height / 2 }; });
const backBox = await page.$eval('#draggable-list1', el => { const r = el.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + 40 }; });
await page.mouse.move(firstIn2.x, firstIn2.y);
await page.mouse.down();
await page.mouse.move(firstIn2.x + 5, firstIn2.y + 5, { steps: 3 });
await page.mouse.move(backBox.x, backBox.y, { steps: 10 });
await page.mouse.up();
ok('drag back restored counts', await page.$$eval('#draggable-list1 .item', i => i.length) === 4 &&
   await page.$$eval('#draggable-list2 .item', i => i.length) === 4);

// 3. keyboard reorder
await page.$eval('#draggable-list3 .item', el => el.focus());
const kbBefore = await page.$eval('#draggable-list3', ul => Array.from(ul.children).map(li => li.dataset.type).join(','));
await page.keyboard.press('Enter');       // pick up
await page.keyboard.press('ArrowDown');   // move down
await page.keyboard.press('Enter');       // drop
const kbAfter = await page.$eval('#draggable-list3', ul => Array.from(ul.children).map(li => li.dataset.type).join(','));
ok('keyboard reorder', kbBefore !== kbAfter, kbBefore + ' -> ' + kbAfter);
ok('no keygrab left', await page.$$eval('.is-keygrab', e => e.length) === 0);

// 4. step navigation
await page.click('[data-disc-next]');
ok('next -> step 1', await page.$eval('.pane.is-active', p => p.dataset.stepPane) === '1');
ok('progress 25%', await page.$eval('#discProgress', b => b.style.width) === '25%');
await page.click('.tab[data-step-btn="7"]');
ok('tab jump -> step 7', await page.$eval('.pane.is-active', p => p.dataset.stepPane) === '7');
ok('finish visible on step 7', !(await page.$eval('[data-disc-finish]', b => b.hidden)));
ok('next hidden on step 7', await page.$eval('[data-disc-next]', b => b.hidden));
ok('tab aria-selected', await page.$eval('.tab[data-step-btn="7"]', t => t.getAttribute('aria-selected')) === 'true');
await page.click('[data-disc-prev]');
ok('prev -> step 6', await page.$eval('.pane.is-active', p => p.dataset.stepPane) === '6');
await page.click('.tab[data-step-btn="0"]');

// 5. finish + score check (independent computation)
await page.click('.tab[data-step-btn="7"]');
await page.click('[data-disc-finish]');
const visible = await page.$eval('#result', r => !r.hidden);
ok('result shown after finish', visible);
ok('wizard hidden', await page.$eval('#wizard', w => w.hidden));

const expected = await page.evaluate(() => {
  const maj = [], min = [];
  document.querySelectorAll('.list').forEach(ul => {
    const items = Array.from(ul.children).filter(n => n.classList.contains('item'));
    items.forEach((li, idx) => {
      const t = li.getAttribute('data-type');
      if (idx === 0) maj.push(t);
      if (idx === 3) min.push(t);
    });
  });
  const c = (a, ch) => a.reduce((s, v) => s + (v === ch ? 1 : 0), 0);
  const sc = { d: c(maj, 'd') - c(min, 'd'), i: c(maj, 'i') - c(min, 'i'),
               s: c(maj, 's') - c(min, 's'), c: c(maj, 'c') - c(min, 'c') };
  return 'D:' + sc.d + ', I:' + sc.i + ', S:' + sc.s + ', C:' + sc.c;
});
const shown = await page.$eval('#scoreLine', s => s.textContent);
ok('score matches independent calc', shown === expected, shown + ' vs ' + expected);
const sumOk = await page.evaluate(() => {
  const m = shown.match(/D:(-?\d+), I:(-?\d+), S:(-?\d+), C:(-?\d+)/);
  return m && (+m[1] + +m[2] + +m[3] + +m[4]) === 0;
});
ok('score sums to 0', sumOk);
const chips = await page.$$eval('.chip__value', v => v.map(x => x.textContent).join(','));
ok('chips filled', /^-?\d+,-?\d+,-?\d+,-?\d+$/.test(chips), chips);

// 6. restart
await page.click('#btnRestart');
ok('restart shows wizard', await page.$eval('#wizard', w => !w.hidden));
ok('restart step 0', await page.$eval('.pane.is-active', p => p.dataset.stepPane) === '0');
ok('restart 96 items', await page.$$eval('.item', i => i.length) === 96);
ok('restart initial order list1',
   await page.$eval('#draggable-list1 .item', el => el.dataset.type) === 'i');

// 7. screenshots
await page.click('.tab[data-step-btn="0"]');
await page.screenshot({ path: '/tmp/shot-start.png' });
await page.click('[data-disc-next]');
await page.screenshot({ path: '/tmp/shot-step.png' });
await page.click('.tab[data-step-btn="7"]');
await page.click('[data-disc-finish]');
await page.screenshot({ path: '/tmp/shot-result.png' });

// 8. mobile viewport sanity (coarse touch => drag via handle)
const page2 = await browser.newPage();
await page2.setViewport({ width: 390, height: 844, hasTouch: true, isMobile: true });
const mErrors = [];
page2.on('pageerror', e => mErrors.push(e.message));
await page2.goto(FILE, { waitUntil: 'load' });
await page2.click('[data-disc-next]');
const mobOk = await page2.$eval('.pane.is-active', p => p.dataset.stepPane) === '1';
ok('mobile next works', mobOk && mErrors.length === 0, mErrors.join('; '));

ok('no external requests', external.length === 0, external.join(','));
ok('no JS errors (desktop)', errors.length === 0, errors.join(' | '));

await browser.close();

let fails = 0;
for (const [st, name, extra] of results) {
  if (st === 'FAIL') fails++;
  console.log(st + '  ' + name + (extra && st === 'FAIL' ? '  [' + extra + ']' : ''));
}
console.log(fails === 0 ? '\nALL PASS (' + results.length + ')' : '\nFAILURES: ' + fails);

